import{_ as r,o as i,c as t,ag as n}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Eigenes Framework","description":"","frontmatter":{},"headers":[],"relativePath":"de/bridge/custom.md","filePath":"de/bridge/custom.md"}'),a={name:"de/bridge/custom.md"};function d(s,e,o,l,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="eigenes-framework" tabindex="-1">Eigenes Framework <a class="header-anchor" href="#eigenes-framework" aria-label="Permalink to &quot;Eigenes Framework&quot;">​</a></h1><p>Du nutzt ein Framework, das die Bridge nicht unterstützt, oder eine stark angepasste Version? Binde es selbst an: Jedes Nayretis Skript nutzt es dann.</p><p>Die Datei <code>nay_lib/bridge/custom.lua</code> wird lesbar ausgeliefert, außerhalb von Cfx Escrow. Sie enthält zwei Tabellen, eine für den Server und eine für den Client, mit jeder Funktion, die die Skripte brauchen: Spieler und Job auslesen, Geld, Items, Benachrichtigungen. Jede Funktion ist in der Datei mit ihren Argumenten und den Werten dokumentiert, die sie zurückgeben muss.</p><h2 id="schritte" tabindex="-1">Schritte <a class="header-anchor" href="#schritte" aria-label="Permalink to &quot;Schritte&quot;">​</a></h2><ol><li><p>Öffne <code>nay_lib/bridge/custom.lua</code> und implementiere jede Funktion der Server- und Client-Tabelle mit den Exports oder Events deines Frameworks.</p></li><li><p>Erzwinge in der <code>server.cfg</code> den eigenen Adapter:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;custom&quot;</span></span></code></pre></div></li><li><p>Starte den Server neu. Die Datei wird von jeder Ressource gelesen, die <code>nay_lib</code> nutzt, starte also nach jeder Änderung alle neu.</p></li></ol><p>Die Konsole bestätigt es beim Start: <code>Bridge ready: framework=custom ...</code>.</p><h2 id="was-die-bridge-dir-schon-abnimmt" tabindex="-1">Was die Bridge dir schon abnimmt <a class="header-anchor" href="#was-die-bridge-dir-schon-abnimmt" aria-label="Permalink to &quot;Was die Bridge dir schon abnimmt&quot;">​</a></h2><p>Du musst nur mit deinem Framework sprechen. Die Bridge selbst:</p><ul><li>prüft Beträge und Konten (<code>cash</code> und <code>bank</code>, ganze positive Beträge);</li><li>prüft den Kontostand, bevor Geld abgezogen wird, und die Anzahl, bevor Items entfernt werden;</li><li>meldet den Skripten, wenn ein Spieler die Verbindung trennt.</li></ul><p>Brauchst du Hilfe? Eröffne einen Beitrag in <code>#support</code> auf dem <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Nayretis Discord</a>.</p>',10)])])}const g=r(a,[["render",d]]);export{p as __pageData,g as default};
